const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const line of envContent.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match) continue;

    const [, key, rawValue] = match;
    env[key] = rawValue.trim().replace(/^['"]|['"]$/g, '');
  }

  return env;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const url = new URL(databaseUrl);
    const host = url.hostname || null;
    const port = url.port || null;
    const database = url.pathname ? url.pathname.replace(/^\//, '') : null;

    return {
      scheme: url.protocol.replace(':', ''),
      host,
      port,
      database,
      redactedUrl: `${url.protocol}//***:***@${url.host}${url.pathname}`,
    };
  } catch {
    return {
      scheme: null,
      host: null,
      port: null,
      database: null,
      redactedUrl: '[unparseable DATABASE_URL]',
    };
  }
}

function fingerprintEnv(env) {
  const sorted = Object.keys(env)
    .sort()
    .reduce((acc, key) => {
      acc[key] = env[key];
      return acc;
    }, {});

  return crypto
    .createHash('sha256')
    .update(JSON.stringify(sorted))
    .digest('hex');
}

async function sendAuditLog(payload) {
  try {
    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    console.log(`Audit log sent: ${response.status} ${response.statusText}`);
  } catch (error) {
    console.warn(`Failed to send audit log: ${error.message}`);
  }
}

async function main() {
  const env = parseEnvFile(envTestPath);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  const dbInfo = redactDatabaseUrl(databaseUrl);
  console.log(`Connected successfully using DATABASE_URL: ${dbInfo.redactedUrl}`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  await sendAuditLog({
    event: 'migration_run_started',
    envFile: '.env.test',
    timestamp: new Date().toISOString(),
    database: dbInfo,
    envFingerprint: fingerprintEnv(env),
    envKeys: Object.keys(env).sort(),
    migrationCount: files.length,
    migrations: files,
  });

  for (const file of files) {
    console.log(`Would apply migration: ${file}`);
  }
}

main();
```

